cd /workspace/dataset && python3 - <<'EOF'
import subprocess

def run(word):
    p = subprocess.run(['./test20_executable', word], capture_output=True)
    if p.returncode != 0:
        return None
    return p.stdout.split(b'\n')

def model(inp: bytes) -> bytes:
    out = bytearray()
    for b in inp:
        if 0x30 <= b <= 0x39 or 0x61 <= b <= 0x7a: out.append(b)
        elif 0x41 <= b <= 0x5a: out.append(b+0x20)
        elif b == 0x20: out.append(0x2d)
    s = bytes(out).strip(b'-')
    return s

# Exhaustive byte sweep at position 0 (byte + 'b'), at end ('a' + byte), and alone
bad = []
for byte in range(1, 256):
    if byte == 0x0a: continue  # handle separately
    for tmpl in [bytes([byte])+b'b', b'a'+bytes([byte]), bytes([byte]), bytes([byte])*3, b'a'+bytes([byte])+b'b']:
        try:
            w = tmpl.decode('latin-1')
        except: continue
        p = subprocess.run(['./test20_executable', tmpl], capture_output=True)
        if p.returncode != 0:
            continue
        lines = p.stdout.split(b'\n')
        if len(lines) < 12: 
            bad.append((tmpl, 'shortout', p.stdout)); continue
        got = lines[10]
        exp = model(tmpl)
        if got != exp:
            bad.append((tmpl, got, exp))
        got12 = lines[11]
        exp12 = model(b'A '+tmpl+b' Test')
        if got12 != exp12:
            bad.append((tmpl+b'|L12', got12, exp12))
print("mismatches:", len(bad))
for x in bad[:40]: print(x)
EOF

cd /workspace/dataset && cat > /tmp/model.pl <<'EOF'
sub model {
    my ($in) = @_;
    my $out = '';
    for my $b (unpack("C*", $in)) {
        if (($b>=0x30 && $b<=0x39) || ($b>=0x61 && $b<=0x7a)) { $out .= chr($b); }
        elsif ($b>=0x41 && $b<=0x5a) { $out .= chr($b+0x20); }
        elsif ($b==0x20) { $out .= '-'; }
    }
    $out =~ s/^-+//; $out =~ s/-+$//;
    return $out;
}
sub probe {
    my ($w) = @_;
    my $pid = open(my $fh, "-|");
    if ($pid == 0) { open(STDERR,'>','/dev/null'); exec('./test20_executable', $w); exit 127; }
    local $/; my $out = <$fh>; close($fh); my $rc = $?;
    return (undef, $rc) if $rc != 0;
    my @lines = split(/\n/, $out, -1);
    return (\@lines, 0);
}
1;
EOF
